'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const authSource=fs.readFileSync(path.join(__dirname,'employee-auth.cjs'),'utf8').split('const user=')[0];const authCreate=new Function('require','__dirname',authSource+';return create')(require('node:module').createRequire(path.join(__dirname,'employee-auth.cjs')),__dirname);
const code=fs.readFileSync(path.join(__dirname,'../business-api.js'),'utf8');
const user={id:'staff-one',name:'招生老师',username:'staff-one',roleIds:['operations'],permissions:['lead.create','lead.read','course.read','course.create','class.read','class.create','schedule.read','student.read','session.move','enrollment.create','order.confirmReceipt'],scope:{type:'all'},mustChangePassword:false,version:1};
const object=(properties,required=[])=>({type:'object',properties,required,additionalProperties:false}),string={type:'string'};
const operations=[{id:'lead.create',label:'创建线索',permission:'lead.create',implemented:true,execution:'server',inputSchema:object({name:string,phone:string,source:string},['name','phone','source'])},{id:'course.create',label:'创建课程',permission:'course.create',implemented:true,execution:'server',inputSchema:object({name:string,priceCents:{type:'integer'},lessons:{type:'array',items:object({title:string,durationMinutes:{type:'integer'}},['title','durationMinutes'])}},['name','priceCents','lessons'])},{id:'class.create',label:'创建班级',permission:'class.create',implemented:true,execution:'server',inputSchema:object({name:string,courseId:string},['name','courseId'])},{id:'enrollment.create',label:'学生报名',permission:'enrollment.create',implemented:true,execution:'server',inputSchema:object({studentId:string,classId:string},['studentId','classId'])},{id:'order.confirmReceipt',label:'确认线下收款',permission:'order.confirmReceipt',implemented:true,execution:'server',inputSchema:object({orderId:string,amountCents:{type:'integer'},reference:string,method:{type:'string',enum:['cash','bank']}},['orderId','amountCents','reference','method'])}];
function snapshot(revision=1){return {revision,capabilities:{businessReady:true,paymentProvider:false},state:{courses:[{id:'c1',name:'真实数学课',priceCents:120050}],classes:[{id:'cl1',name:'数学一班',courseId:'c1',schedule:[]}],students:[{id:'s1',name:'服务器学生',phone:'13812345678'}],leads:[{id:'l1',name:'服务器线索',phone:'13800000001'}],orders:[{id:'o1',studentId:'s1',classId:'cl1',amountCents:120050,paidCents:0}],campuses:[],staff:[],dictionary:{},settings:{},activities:{coupon:[],group:[],joint:[]},forms:[],decor:{},directory:[]}}}
const response=(body,status=200)=>({ok:status<400,status,json:async()=>body});
async function create({pending=false,moreOperations=[],userOverride=user,snapshotData=snapshot()}={}){const b=await authCreate(userOverride);const calls=[];let responder=async(url,opts)=>url.endsWith('/v1/state')?response(snapshotData):url.endsWith('/v1/catalog')?response({operations:[...operations,...moreOperations]}):response({previewToken:'valid-preview',revision:1,result:{totalCents:120050}});b.respond(async(url,opts={})=>{calls.push({url:String(url),options:opts});return responder(String(url),opts)});if(pending)responder=()=>new Promise(()=>{});b.run(code);await new Promise(resolve=>setImmediate(resolve));return {...b,calls,respondBusiness(fn){responder=fn}}}
test('live mode clears all seeded browser business data before server loading finishes',async()=>{const b=await create({pending:true});assert.equal(b.run('a.students.length'),0);assert.equal(b.run('leadState.leads.length'),0);assert.equal(b.run('mallState.activities.coupon.length'),0);assert.match(b.elements.get('#view').innerHTML,/正在加载服务器数据/)});
test('real bound sidebar clicks leave the business form, route through navigation, and back restores search',async()=>{const b=await create();const menu=page=>b.lists.get('.menu-item').find(x=>x.dataset.page===page);assert.equal(b.lists.get('.menu-item').length,37);b.run("businessAPI.open('class.create')");assert.match(b.elements.get('#view').innerHTML,/id="business-form"/);menu('course').click();assert.equal(b.run('state.page'),'course');assert.doesNotMatch(b.elements.get('#view').innerHTML,/id="business-form"/);assert.match(b.elements.get('#crumb').textContent,/课程管理/);b.run("businessAPI.search('数学')");menu('students').click();assert.equal(b.run('state.page'),'students');b.run('businessAPI.back()');assert.equal(b.run('state.page'),'course');assert.equal(b.run('businessAPI.status().operation'),null);assert.match(b.elements.get('#view').innerHTML,/value="数学"/);menu('classes').click();assert.equal(b.run('state.page'),'classes');assert.doesNotMatch(b.elements.get('#view').innerHTML,/id="business-form"/) });
test('all 37 real sidebar menu elements are bound and permission-filtered',async()=>{const b=await create();const items=b.lists.get('.menu-item[data-page]');assert.equal(items.length,37);for(const item of items){assert.equal(typeof item.listeners.click,'function',item.dataset.page);assert.equal(item.hidden,!b.run(`permissionCanVisit(${JSON.stringify(item.dataset.page)})`),item.dataset.page)}for(const item of items){if(item.hidden)continue;const current=b.run('state.page'),allowed=b.run(`permissionCanVisit(${JSON.stringify(item.dataset.page)})`);assert.equal(allowed,true,item.dataset.page);item.click();assert.equal(b.run('state.page'),item.dataset.page,item.dataset.page)}});
test('delayed employee account reads can be replaced by a later real menu route',async()=>{const admin={...user,roleIds:['superadmin'],permissions:[...user.permissions,'account.update','role.grant']};const b=await authCreate(admin);let releaseUsers,usersRequests=0;const roles={roles:[{id:'superadmin',label:'超级管理员',defaultScope:'all'}],permissions:[]};b.respond(async url=>{if(String(url).endsWith('/v1/admin/users')){usersRequests++;if(usersRequests===1)return new Promise(resolve=>releaseUsers=resolve);return response({users:[]})}if(String(url).endsWith('/v1/roles'))return response(roles);if(String(url).endsWith('/v1/state'))return response(snapshot());if(String(url).endsWith('/v1/catalog'))return response({operations});return response({})});b.run(code);await new Promise(r=>setImmediate(r));const menu=page=>b.lists.get('.menu-item').find(x=>x.dataset.page===page);menu('staff').click();await new Promise(r=>setImmediate(r));assert.equal(usersRequests,1);menu('positions').click();await new Promise(r=>setImmediate(r));assert.equal(b.run('state.page'),'positions');releaseUsers(response({users:[{id:'late-user',name:'迟到员工',username:'late',roleIds:['sales'],scope:{type:'own'}}]}));await new Promise(r=>setImmediate(r));assert.equal(b.run('state.page'),'positions');assert.match(b.elements.get('#crumb').textContent,/职位与角色/);assert.match(b.elements.get('#view').innerHTML,/超级管理员/);assert.doesNotMatch(b.elements.get('#view').innerHTML,/迟到员工/)});
test('real account menu routes share the business back stack across staff, roles and permissions',async()=>{const admin={...user,roleIds:['superadmin'],permissions:[...user.permissions,'account.update','role.grant']};const b=await authCreate(admin);const roleData={roles:[{id:'superadmin',label:'超级管理员',defaultScope:'all',description:'全平台管理'}],permissions:[{id:'course.read',label:'查看课程',description:'读取课程资料'}]};b.respond(async url=>{const u=String(url);if(u.endsWith('/v1/admin/users'))return response({users:[{id:'u1',name:'员工甲',username:'staff-a',roleIds:['superadmin'],scope:{type:'all'}}]});if(u.endsWith('/v1/roles'))return response(roleData);if(u.endsWith('/v1/state'))return response(snapshot());if(u.endsWith('/v1/catalog'))return response({operations});return response({})});b.run(code);await new Promise(r=>setImmediate(r));const menu=page=>b.lists.get('.menu-item').find(x=>x.dataset.page===page);for(const page of ['staff','positions','permissions','course']){menu(page).click();await new Promise(r=>setImmediate(r));assert.equal(b.run('state.page'),page);assert.equal(b.elements.get('#crumb').textContent.includes(page==='staff'?'员工账号':page==='positions'?'职位':page==='permissions'?'权限':'课程'),true)}b.run('businessAPI.back()');assert.equal(b.run('state.page'),'permissions');assert.match(b.elements.get('#view').innerHTML,/选择员工进行授权/);b.run('businessAPI.back()');assert.equal(b.run('state.page'),'positions');assert.match(b.elements.get('#view').innerHTML,/超级管理员/);b.run('businessAPI.back()');assert.equal(b.run('state.page'),'staff');assert.match(b.elements.get('#view').innerHTML,/员工甲/)});
test('a successful searched business operation restores the account route and its rendered account list',async()=>{const admin={...user,roleIds:['superadmin'],permissions:[...user.permissions,'account.update','role.grant']};const b=await authCreate(admin);b.respond(async(url,opts={})=>{const u=String(url);if(u.endsWith('/v1/admin/users'))return response({users:[{id:'u1',name:'员工甲',username:'staff-a',roleIds:['superadmin'],scope:{type:'all'}}]});if(u.endsWith('/v1/roles'))return response({roles:[],permissions:[]});if(u.endsWith('/v1/state'))return response(snapshot());if(u.endsWith('/v1/catalog'))return response({operations});if(u.endsWith('/course.create/preview'))return response({previewToken:'course-preview',revision:1,result:{record:{name:'搜索创建课程'}}});if(u.endsWith('/course.create/execute'))return response({revision:2,state:snapshot(2).state,result:{record:{name:'搜索创建课程'}}});return response({})});b.run(code);await new Promise(r=>setImmediate(r));b.run("nav('staff')");await new Promise(r=>setImmediate(r));b.run("workflowSearchEntries('创建课程').find(x=>x.meta==='操作').action()");assert.equal(b.run('state.page'),'businessOperation');b.run("businessAPI.change(['name'],'搜索创建课程');businessAPI.change(['priceCents'],12000);businessAPI.change(['lessons'],[{title:'第一讲',durationMinutes:60}])");assert.equal(await b.run('businessAPI.preview()'),true);assert.equal(await b.run('businessAPI.execute()'),true);assert.equal(b.run('state.page'),'staff');assert.doesNotMatch(b.elements.get('#view').innerHTML,/id="business-form"/);assert.match(b.elements.get('#view').innerHTML,/员工甲/);assert.match(b.elements.get('#crumb').textContent,/员工账号与权限/) });
test('account password writes block every route entry until one-time credentials are shown',async()=>{const admin={...user,roleIds:['superadmin'],permissions:[...user.permissions,'account.update','role.grant']};const b=await authCreate(admin);let releaseReset;b.respond(async url=>{const u=String(url);if(u.includes('/reset-password'))return new Promise(resolve=>releaseReset=resolve);if(u.endsWith('/v1/admin/users'))return response({users:[{id:'u1',name:'员工甲',username:'staff-a',roleIds:['sales'],scope:{type:'own'}}]});if(u.endsWith('/v1/roles'))return response({roles:[],permissions:[]});if(u.endsWith('/v1/state'))return response(snapshot());if(u.endsWith('/v1/catalog'))return response({operations});return response({})});b.run(code);await new Promise(r=>setImmediate(r));const menu=page=>b.lists.get('.menu-item').find(x=>x.dataset.page===page);menu('staff').click();await new Promise(r=>setImmediate(r));const saving=b.run("employeeAuth.resetPassword('u1')");await new Promise(r=>setImmediate(r));menu('course').click();assert.equal(b.run('state.page'),'staff');assert.equal(b.run('workspaceBack()'),false);const pageEntry=b.run("workflowSearchEntries('课程管理').find(x=>x.meta==='页面')");assert.ok(pageEntry);pageEntry.action();assert.equal(b.run('state.page'),'staff');const opEntry=b.run("workflowSearchEntries('创建课程').find(x=>x.meta==='操作')");assert.ok(opEntry);opEntry.action();assert.equal(b.run('state.page'),'staff');b.run("nav('course')");assert.equal(b.run('state.page'),'staff');releaseReset(response({user:{id:'u1',username:'temp'},initialPassword:'Initial-Test!23456'}));await saving;assert.equal(b.run('state.page'),'staff');assert.match(b.elements.get('#view').innerHTML,/Initial-Test!23456/) });
test('menu page actions keep temporary move, makeup and receipts workflows fixed to their own meaning',async()=>{const more=[{id:'makeup.assign',label:'安排补课或临时转班',permission:'enrollment.create',implemented:true,execution:'server',inputSchema:object({kind:{type:'string',enum:['makeup','temporary']},enrollmentId:string},['kind','enrollmentId'])},{id:'makeup.cancel',label:'取消课次预约',permission:'enrollment.create',implemented:true,execution:'server',inputSchema:object({adjustmentId:string},['adjustmentId'])},{id:'settings.update',label:'更新系统设置',permission:'order.confirmReceipt',implemented:true,execution:'server',inputSchema:{...object({section:{type:'string',enum:['receipts','organization']},values:{type:'object',properties:{accountName:string,accountNumber:string}}},['section','values']),properties:{section:{type:'string',enum:['receipts','organization']},values:{type:'object','x-fieldsBySection':{receipts:object({accountName:string,accountNumber:string}),organization:object({name:string})}}}}}];const b=await create({moreOperations:more});const menu=page=>b.lists.get('.menu-item').find(x=>x.dataset.page===page);menu('tempMove').click();assert.equal(b.run('state.page'),'tempMove');assert.doesNotMatch(b.elements.get('#view').innerHTML,/取消课次预约/);assert.match(b.elements.get('#view').innerHTML,/临时调班/);b.run("businessAPI.open('makeup.assign',{kind:'temporary'})");assert.match(b.elements.get('#view').innerHTML,/data-business-type="string" value="temporary"/);b.run("businessAPI.open('makeup.assign')");assert.match(b.elements.get('#view').innerHTML,/data-business-path="\[&quot;kind&quot;\]"/);menu('financeReceipts').click();b.run("businessAPI.open('settings.update',{section:'receipts'})");assert.match(b.elements.get('#view').innerHTML,/value="receipts"/);assert.match(b.elements.get('#view').innerHTML,/收款账户名称/);assert.doesNotMatch(b.elements.get('#view').innerHTML,/机构名称/)});
test('registration, transfer, withdrawal, supplement and settings pages keep distinct actions and rows',async()=>{
 const entries=[['enrollment.create','办理报名',['studentId']],['enrollment.batchCreate','批量报名',['rows']],['enrollment.transfer','永久转班',['enrollmentId']],['enrollment.batchTransfer','批量永久转班',['enrollmentIds']],['enrollment.withdraw','办理退课',['enrollmentId']],['makeup.assign','安排补课或临时转班',['kind','enrollmentId']],['makeup.cancel','取消课次预约',['adjustmentId']],['order.confirmReceipt','确认线下收款',['orderId']],['order.paymentLink','生成缴费链接',['orderId']],['settings.update','更新系统设置',['section','values']]];
 const ops=entries.map(([id,label,required])=>({id,label,permission:id.startsWith('enrollment.')?'enrollment.create':id.startsWith('makeup.')?'session.move':id.startsWith('order.')?'order.confirmReceipt':'settings.update',implemented:true,execution:'server',inputSchema:object(Object.fromEntries(required.map(k=>[k,k==='values'?{type:'object',properties:{}}:string])),required)}));
 const actor={...user,permissions:[...new Set([...user.permissions,'enrollment.transfer','enrollment.withdraw','session.move','order.paymentLink','settings.read','settings.update'])]};
 const data=snapshot();data.state.enrollments=[{id:'e1',studentId:'s1',classId:'cl1',status:'active'},{id:'e2',studentId:'s1',classId:'cl1',status:'pending'}];data.state.orders=[];data.state.orders=[{id:'o-pending',studentId:'s1',classId:'cl1',amountCents:1000,paidCents:0,status:'pending'},{id:'o-paid',studentId:'s1',classId:'cl1',amountCents:1000,paidCents:1000,status:'paid'},{id:'o-cancelled',studentId:'s1',classId:'cl1',amountCents:1000,paidCents:0,status:'cancelled'},{id:'o-closed',studentId:'s1',classId:'cl1',amountCents:1000,paidCents:0,status:'closed'}];data.state.settings={organization:{name:'机构设置'},receipts:{accountName:'收款户名',accountNumber:'收款账号'}};
 const b=await create({moreOperations:ops,userOverride:actor,snapshotData:data}),view=()=>b.elements.get('#view').innerHTML;
 for(const [page,yes,no]of [['enroll',['办理报名','批量报名'],['永久转班','办理退课','取消课次预约']],['transfer',['批量永久转班'],['办理报名','批量报名','办理退课']],['withdraw',[],['办理报名','批量报名','永久转班','取消课次预约']]]){b.run(`nav('${page}')`);for(const label of yes)assert.match(view(),new RegExp(label));for(const label of no)assert.doesNotMatch(view(),new RegExp(label));if(page==='transfer'||page==='withdraw'){b.run("businessAPI.expand('enrollments',0)");assert.match(view(),new RegExp(page==='transfer'?'永久转班':'办理退课'))}}
 b.run("nav('supplement')");assert.equal((view().match(/<tr role=\"button\"/g)||[]).length,1);b.run("nav('financeReceipts')");assert.match(view(),/收款户名/);assert.doesNotMatch(view(),/机构设置/);b.run("nav('system')");assert.match(view(),/机构信息/);assert.match(view(),/收款设置/);
});
