test('confirmation resolves newly created sibling references, keeps fees and impact, formats local time and hides unknown metadata',async()=>{const b=await create();const result={student:{id:'STUDENT_NEW',name:'新同学',phone:'13800000088',createdAt:'2026-10-10T08:30:45.000Z',version:3,debugSecret:'do-not-display'},order:{id:'ORDER_PRIVATE',studentId:'STUDENT_NEW',classId:'cl1',amountCents:120050,discountCents:2500,paidCents:0,refundedCents:0,couponVersion:8,status:'pending',payloadHash:'private-hash'},impact:{studentCount:1,sessionCount:2,conflicts:['教室已被占用，请调整时间']}};b.respondBusiness(async()=>response({previewToken:'private-preview-token',revision:1,result}));b.run("businessAPI.open('enrollment.create');businessAPI.change(['studentId'],'s1');businessAPI.change(['classId'],'cl1')");assert.equal(await b.run('businessAPI.preview()'),true);const h=b.elements.get('#view').innerHTML.split('<div id="business-preview">')[1].split('<p id="business-preview-hint"')[0],when=b.run("(()=>{const d=new Date('2026-10-10T08:30:45.000Z'),p=x=>String(x).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())})()");assert.match(h,/新同学/);assert.match(h,/数学一班/);assert.match(h,/¥1200\.50/);assert.match(h,/¥25\.00/);assert.match(h,/¥0\.00/);assert.match(h,/学生人数/);assert.match(h,/课次数量/);assert.match(h,/教室已被占用/);assert.ok(h.includes(when));assert.doesNotMatch(h,/STUDENT_NEW|ORDER_PRIVATE|cl1|版本|debugSecret|do-not-display|payloadHash|private-hash|2026-10-10T08:30/);});

