test('top-bar back button keeps disabled state and accessible label in sync with business navigation',async()=>{const b=await create(),button=b.ctx.document.querySelector('#workspace-back'),attributes=new Map();button.setAttribute=(name,value)=>attributes.set(name,value);assert.equal(button.disabled,true);assert.equal(button.title,'已在起始页面');b.run("businessAPI.open('enrollment.create')");assert.equal(button.disabled,false);assert.equal(button.title,'返回上一页');assert.equal(attributes.get('aria-label'),'返回上一页');b.run('businessAPI.back()');assert.equal(button.disabled,true);assert.equal(button.title,'已在起始页面');assert.equal(attributes.get('aria-label'),'已在起始页面');});

// Exercise the handlers emitted into HTML, with DOM control values, rather than calling change() directly.
function mountBusinessControls(b){const decode=s=>String(s||'').replace(/&quot;|&#39;|&lt;|&gt;|&amp;/g,x=>({'&quot;':'"','&#39;':"'",'&lt;':'<','&gt;':'>','&amp;':'&'}[x])),h=b.elements.get('#view').innerHTML,controls=[];for(const match of h.matchAll(/<(input|select|textarea)\b([^>]*)>/g)){const attrs=Object.fromEntries([...match[2].matchAll(/([\w-]+)(?:="([^"]*)")?/g)].map(x=>[x[1],decode(x[2]??'')]));if(!attrs['data-business-path'])continue;const after=h.slice(match.index+match[0].length),inner=match[1]==='input'?'':after.slice(0,after.indexOf('</'+match[1]+'>'));let value=attrs.value||'';if(match[1]==='select'){const opts=[...inner.matchAll(/<option\b([^>]*)>([\s\S]*?)<\/option>/g)],selected=opts.find(x=>/\bselected\b/.test(x[1]))||opts[0];value=decode(selected?.[1].match(/value="([^"]*)"/)?.[1]||'')}if(match[1]==='textarea')value=decode(inner);const el={value,checked:Object.hasOwn(attrs,'checked'),disabled:Object.hasOwn(attrs,'disabled'),dataset:{businessPath:attrs['data-business-path'],businessType:attrs['data-business-type'],businessOption:attrs['data-business-option']},attrs};controls.push(el)}b.lists.set('#business-form [data-business-path]',controls);return {controls,find(path){const item=controls.find(el=>el.dataset.businessPath===JSON.stringify(path));assert.ok(item,'rendered field '+JSON.stringify(path));return item},event(el,type,value){if(value!==undefined)el.value=value;const handler=el.attrs['on'+type];assert.ok(handler,'rendered '+type+' handler');b.ctx.businessTestControl=el;return b.run('(function(){'+handler+'}).call(businessTestControl)')}}}
async function enrollmentFormFixture(){const b=await realBusiness();let s=await b.commit('campus.create',{name:'输入保留校区',rooms:[{name:'A教室',capacity:20}]});const campusId=s.campuses[0].id;s=await b.commit('course.create',{name:'输入保留数学',grade:'4年级',subject:'数学',priceCents:120000,lessons:[{title:'第一讲',durationMinutes:60}]});s=await b.commit('class.create',{name:'输入保留班',courseId:s.courses[0].id,campusId,room:'A教室',teacherId:b.teacher.id,capacity:20});const classId=s.classes[0].id;b.run(`businessAPI.open('enrollment.create',${JSON.stringify({classId})});businessAPI.studentMode([],true)`);return {...b,campusId,classId}}
test('generated input/change handlers preserve nested new-student fields when campus selection redraws the form',async()=>{const b=await enrollmentFormFixture();try{let dom=mountBusinessControls(b);dom.event(dom.find(['studentDraft','name']),'input','事件录入学生');dom.event(dom.find(['studentDraft','phone']),'input','13800000091');dom.event(dom.find(['studentDraft','grade']),'input','4年级');dom.event(dom.find(['studentDraft','campusId']),'change',b.campusId);dom=mountBusinessControls(b);assert.equal(dom.find(['studentDraft','name']).value,'事件录入学生');assert.equal(dom.find(['studentDraft','phone']).value,'13800000091');assert.equal(dom.find(['studentDraft','grade']).value,'4年级');assert.equal(dom.find(['classId']).value,b.classId);assert.equal(await b.run('businessAPI.preview()'),true,b.run('businessAPI.status().error'));assert.match(b.elements.get('#view').innerHTML,/事件录入学生/);assert.equal(await b.run('businessAPI.execute()'),true);assert.equal(b.store.snapshot().state.students[0].name,'事件录入学生');assert.equal(b.store.snapshot().state.orders.length,1);}finally{b.store.close()}});
test('autofilled DOM values survive redraw and submit without blur, and clicking active new-student mode does not reset them',async()=>{const b=await enrollmentFormFixture();try{let dom=mountBusinessControls(b);dom.find(['studentDraft','name']).value='自动填写学生';dom.find(['studentDraft','phone']).value='13800000092';dom.find(['studentDraft','grade']).value='4年级';dom.event(dom.find(['studentDraft','campusId']),'change',b.campusId);dom=mountBusinessControls(b);assert.equal(dom.find(['studentDraft','name']).value,'自动填写学生');assert.equal(dom.find(['studentDraft','phone']).value,'13800000092');b.run('businessAPI.studentMode([],true)');dom=mountBusinessControls(b);assert.equal(dom.find(['studentDraft','name']).value,'自动填写学生');dom.find(['studentDraft','name']).value='提交前最后输入';dom.find(['studentDraft','phone']).value='13800000093';assert.equal(await b.run('businessAPI.preview()'),true,b.run('businessAPI.status().error'));assert.match(b.elements.get('#view').innerHTML,/提交前最后输入/);assert.equal(await b.run('businessAPI.execute()'),true);const state=b.store.snapshot().state;assert.equal(state.students[0].name,'提交前最后输入');assert.equal(state.students[0].phone,'13800000093');assert.equal(state.students[0].grade,'4年级');assert.equal(state.orders.length,1);}finally{b.store.close()}});

test('DOM autofill after preview cannot commit stale student data without a fresh preview',async()=>{const b=await enrollmentFormFixture();try{let dom=mountBusinessControls(b);dom.find(['studentDraft','name']).value='预览核对学生';dom.find(['studentDraft','phone']).value='13800000094';assert.equal(await b.run('businessAPI.preview()'),true);dom=mountBusinessControls(b);dom.find(['studentDraft','phone']).value='13800000095';assert.equal(await b.run('businessAPI.execute()'),false);assert.match(b.elements.get('#view').innerHTML,/请先检查并预览/);assert.equal(b.store.snapshot().state.students.length,0);dom=mountBusinessControls(b);assert.equal(dom.find(['studentDraft','phone']).value,'13800000095');assert.equal(await b.run('businessAPI.preview()'),true);mountBusinessControls(b);assert.equal(await b.run('businessAPI.execute()'),true);assert.equal(b.store.snapshot().state.students[0].phone,'13800000095');assert.equal(b.store.snapshot().state.orders.length,1);}finally{b.store.close()}});

function trackBusinessRedraws(b){const view=b.elements.get('#view');let value=view.innerHTML,writes=0;Object.defineProperty(view,'innerHTML',{configurable:true,get:()=>value,set(next){writes++;value=next}});return ()=>writes}
test('typing a mall module name syncs the draft without replacing focused form controls; change alone redraws structure',async()=>{const b=await realBusiness();try{b.run("businessAPI.open('store.design.save',{decor:{title:'课程商城',subtitle:'',color:'#315deb',modules:['介绍'],blocks:{介绍:{title:'课程介绍',body:'欢迎了解'}}}})");const dom=mountBusinessControls(b),control=dom.find(['decor','modules',0]),writes=trackBusinessRedraws(b);b.ctx.document.activeElement=control;for(const value of ['介','介绍区','介绍区域']){dom.event(control,'input',value);assert.equal(writes(),0,'input must not replace form DOM');assert.equal(b.ctx.document.activeElement,control)}dom.event(control,'change','介绍区域');assert.equal(writes(),1,'committed module change refreshes dynamic block fields');const next=mountBusinessControls(b);assert.equal(next.find(['decor','modules',0]).value,'介绍区域');assert.match(b.elements.get('#view').innerHTML,/介绍区域/);}finally{b.store.close()}});
test('typing a custom answer whose field key ends in Id never triggers structural rendering or loses text',async()=>{const b=await realBusiness();try{let state=await b.commit('form.create',{title:'文字输入检查',fields:[{id:'answerId',type:'text',title:'咨询说明',required:true}],settings:{quantity:10,maxPerIdentity:1}});const formId=state.forms[0].id;await b.commit('form.publish',{formId});b.run(`businessAPI.open('form.submit',${JSON.stringify({formId})})`);const dom=mountBusinessControls(b),control=dom.find(['answersById','answerId']),writes=trackBusinessRedraws(b);for(const value of ['想','想了解','想了解数学课程']){dom.event(control,'input',value);assert.equal(writes(),0)}assert.equal(await b.run('businessAPI.preview()'),true,b.run('businessAPI.status().error'));mountBusinessControls(b);assert.equal(await b.run('businessAPI.execute()'),true);assert.equal(b.store.snapshot().state.forms[0].submissions[0].answersById.answerId,'想了解数学课程');}finally{b.store.close()}});

async function leadViews({scope={type:'all'},limited=false,superadmin=false}={}){
 const registry=require('../backend/src/business-crm.cjs').operations.filter(o=>o.id.startsWith('lead.')&&!o.id.startsWith('lead.profile'));
 const actor={...user,scope,roleIds:superadmin?['superadmin']:['sales'],permissions:limited?['lead.read']:['lead.read','lead.create','lead.follow','lead.assign','lead.transfer','lead.release','leadPolicy.preview','leadPolicy.publish','course.read']};
 const b=await authCreate(actor),now=Date.now(),at=hours=>new Date(now+hours*3600000).toISOString(),data=snapshot(),base={phone:'13800000001',source:'扫码表单',createdAt:at(-24),assignedAt:at(-12),firstFollowAt:at(-10),assignmentFollowAt:at(-10),status:'assigned',stage:'跟进中',intent:'中意向',ownerId:actor.id,registrarId:'other',owner:'招生老师'};
 data.state.directory=[actor,{id:'other',name:'另一位老师'}];data.state.leadPolicy={reserveDays:14,reclaimDays:21,firstFollowHours:4};
 const row=(id,patch={})=>({id,name:id, ...base,...patch});
 data.state.leads=[row('他人到期',{ownerId:'other',nextFollowAt:at(-1)}),row('本人登记已转交',{registrarId:actor.id,ownerId:'other',source:'活动报名'}),row('本人到期',{nextFollowAt:at(-1)}),row('本人未来预约',{nextFollowAt:at(48)}),row('本人已归档',{registrarId:actor.id,status:'cold',stage:'已归档',nextFollowAt:at(-1)}),row('本人已报名',{status:'converted',stage:'已报名',nextFollowAt:at(-1)}),row('本人登记公海',{registrarId:actor.id,ownerId:null,status:'new',stage:'新线索'}),row('兼容登记字段',{registrarId:undefined,registrantId:actor.id,ownerId:'other',intent:'高意向'}),row('兼容创建字段',{registrarId:undefined,createdBy:actor.id,ownerId:'other',source:'电话'}),row('两项待办',{assignedAt:at(-6),firstFollowAt:at(-48),assignmentFollowAt:null,nextFollowAt:at(-2)}),row('刚分配',{assignedAt:at(-1),firstFollowAt:null,assignmentFollowAt:null}),row('回收候选',{assignedAt:at(-30*24),firstFollowAt:at(-29*24),assignmentFollowAt:at(-29*24),lastFollowAt:at(-22*24)}),row('近期有效沟通',{assignedAt:at(-30*24),firstFollowAt:at(-29*24),assignmentFollowAt:at(-29*24),lastFollowAt:at(-24)}),row('过往登记',{createdAt:at(-100*24),registrarId:actor.id,ownerId:'other'}),row('同名登记人',{registrarId:undefined,registrar:actor.name,ownerId:'other'})];
 if(superadmin)data.state.classes=[];
 const calls=[];let descriptor=registry.map(({run,...o})=>({...o,implemented:true,execution:'server'}));
 b.respond(async(url,opts={})=>{url=String(url);calls.push({url,options:opts});return response(url.endsWith('/v1/state')?data:url.endsWith('/v1/catalog')?{operations:descriptor}:{previewToken:'lead-preview',revision:1,result:{record:{name:'跟进结果'}}})});
 b.run(code);await new Promise(r=>setImmediate(r));return {...b,data,actor,calls,at};
}
const leadRowIds=b=>[...b.elements.get('#view').innerHTML.matchAll(/data-lead-row="([^"]+)"/g)].map(m=>m[1]);
test('registration lists original registrar only, preserves transfer and uses original dates for compact statistics',async()=>{const b=await leadViews();b.run("nav('quickRegister')");assert.deepEqual(leadRowIds(b),['本人登记已转交','本人已归档','本人登记公海','兼容登记字段','兼容创建字段','过往登记']);let h=b.elements.get('#view').innerHTML;assert.match(h,/<span>累计登记<\/span><strong>6<\/strong>/);assert.match(h,/<span>有效线索（近90天）<\/span><strong>5<\/strong>/);assert.match(h,/单个登记/);assert.match(h,/批量导入/);assert.doesNotMatch(h,/id="business-lead-filters"/);assert.doesNotMatch(h,/T\d\d:\d\d:\d\d\.\d{3}Z/);b.run("businessAPI.leadFilterToggle();businessAPI.leadFilter('intent','高意向')");assert.deepEqual(leadRowIds(b),['兼容登记字段']);assert.match(b.elements.get('#view').innerHTML,/aria-expanded="true"/);b.run("businessAPI.leadFilter('intent','');businessAPI.leadFilter('stage','已归档')");assert.deepEqual(leadRowIds(b),['本人已归档']);b.run('businessAPI.leadFilterReset()');assert.equal(leadRowIds(b).length,6);});
test('registration filters exact local day boundaries and original stage, independent from assigned time',async()=>{const b=await leadViews(),d=new Date();d.setDate(d.getDate()-3);const date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),target=b.data.state.leads.find(r=>r.id==='本人登记已转交');target.createdAt=new Date(date+'T23:59:59').toISOString();target.assignedAt=b.at(-1);await b.run('businessAPI.reload()');b.run(`nav('quickRegister');businessAPI.leadFilter('from',${JSON.stringify(date)});businessAPI.leadFilter('to',${JSON.stringify(date)})`);assert.deepEqual(leadRowIds(b),['本人登记已转交']);});
test('today tasks use current owner and assignment epoch, deduplicate reasons, exclude future and terminal records',async()=>{const b=await leadViews();b.run("nav('leadTodo')");assert.deepEqual(leadRowIds(b),['两项待办','本人到期']);const h=b.elements.get('#view').innerHTML;assert.match(h,/<span>待跟进<\/span><strong>2<\/strong>/);assert.match(h,/<span>预约逾期<\/span><strong>2<\/strong>/);assert.match(h,/<span>首次跟进超时<\/span><strong>1<\/strong>/);assert.match(h,/同一线索只计一次/);assert.equal((h.match(/data-lead-row="两项待办"/g)||[]).length,1);b.run("businessAPI.leadExpand('两项待办')");const action=b.elements.get('#view').innerHTML.split('<div class="actions">')[2]||b.elements.get('#view').innerHTML;assert.match(action,/primary[^>]*onclick="businessAPI.leadAction\(&quot;两项待办&quot;,'lead.followup'\)/);});
test('today includes an appointment later today but not tomorrow, and a completed assignment follow-up clears initial overdue',async()=>{const b=await leadViews(),end=new Date();end.setHours(23,59,59,999);const row=b.data.state.leads.find(r=>r.id==='本人未来预约');row.nextFollowAt=end.toISOString();b.data.state.leads.find(r=>r.id==='两项待办').assignmentFollowAt=b.at(-1);await b.run('businessAPI.reload()');b.run("nav('leadTodo')");assert.ok(leadRowIds(b).includes('本人未来预约'));assert.match(b.elements.get('#view').innerHTML,/今日预约/);assert.match(b.elements.get('#view').innerHTML,/<span>首次跟进超时<\/span><strong>0<\/strong>/);});
test('my leads uses current owner and separate active, enrolled and archived underline tabs',async()=>{const b=await leadViews();b.run("nav('myLeads')");assert.deepEqual(leadRowIds(b),['本人到期','本人未来预约','两项待办','刚分配','回收候选','近期有效沟通']);assert.match(b.elements.get('#view').innerHTML,/business-tabs/);b.run("businessAPI.leadTab('leadMineTab','converted')");assert.deepEqual(leadRowIds(b),['本人已报名']);b.run("businessAPI.leadTab('leadMineTab','archived')");assert.deepEqual(leadRowIds(b),['本人已归档']);assert.doesNotMatch(b.elements.get('#view').innerHTML,/data-lead-row="本人登记已转交"/);});
test('management has public, assignment, recyclable and archive views, with permitted policy actions',async()=>{const b=await leadViews();b.run("nav('leadManage')");assert.equal(leadRowIds(b).length,15);assert.match(b.elements.get('#view').innerHTML,/线索保留与回收策略设置/);assert.match(b.elements.get('#view').innerHTML,/试运行策略/);b.run("businessAPI.leadTab('leadManageTab','public')");assert.deepEqual(leadRowIds(b),['本人登记公海']);b.run("businessAPI.leadTab('leadManageTab','recycle')");assert.deepEqual(leadRowIds(b),['回收候选']);b.run("businessAPI.leadTab('leadManageTab','archived')");assert.deepEqual(leadRowIds(b),['本人已归档']);b.run("businessAPI.leadTab('leadManageTab','assigned')");assert.equal(leadRowIds(b).length,12);const readonly=await leadViews({limited:true});readonly.run("nav('leadManage');businessAPI.leadExpand('本人到期')");assert.doesNotMatch(readonly.elements.get('#view').innerHTML,/businessAPI.open\('lead.policy|businessAPI.leadAction\(/);});
test('transferred original registrant keeps readable history without out-of-scope action buttons',async()=>{const b=await leadViews({scope:{type:'own'}});b.run("nav('quickRegister');businessAPI.leadExpand('本人登记已转交')");let h=b.elements.get('#view').innerHTML;assert.match(h,/查看档案/);assert.match(h,/当前记录没有可用操作/);assert.doesNotMatch(h,/businessAPI.leadAction\(&quot;本人登记已转交/);assert.equal(b.run("businessAPI.leadAction('本人登记已转交','lead.followup')"),false);b.run("nav('myLeads');businessAPI.leadExpand('本人到期')");assert.match(b.elements.get('#view').innerHTML,/businessAPI.leadAction\(&quot;本人到期&quot;,'lead.followup'/);});
test('campus write choices match actual campus, while policy publication requires all scope',async()=>{const b=await leadViews({scope:{type:'campus',campusIds:['mine']}});b.data.state.leads[2].campusId='mine';b.data.state.leads[1].campusId='other';await b.run('businessAPI.reload()');b.run("nav('leadManage');businessAPI.leadExpand('本人登记已转交')");assert.doesNotMatch(b.elements.get('#view').innerHTML,/businessAPI.leadAction\(/);assert.doesNotMatch(b.elements.get('#view').innerHTML,/线索保留与回收策略设置/);b.run("businessAPI.leadExpand('本人到期')");assert.match(b.elements.get('#view').innerHTML,/businessAPI.leadAction\(/);});
test('filtered lead row operations use stable IDs after reorder and preserve server preview contract',async()=>{const b=await leadViews();b.run("nav('quickRegister');businessAPI.search('兼容登记字段');businessAPI.leadExpand('兼容登记字段')");assert.deepEqual(leadRowIds(b),['兼容登记字段']);b.data.state.leads.reverse();await b.run('businessAPI.reload()');b.run("businessAPI.leadAction('兼容登记字段','lead.followup');businessAPI.change(['note'],'按筛选档案记录跟进')");assert.equal(await b.run('businessAPI.preview()'),true);const call=b.calls.findLast(c=>c.url.endsWith('/preview')),input=JSON.parse(call.options.body).input;assert.equal(input.leadId,'兼容登记字段');assert.equal(input.note,'按筛选档案记录跟进');assert.equal(call.options.headers['X-CSRF-Token'],'private-csrf');});
test('global lead search opens exact readable record and back restores detail, query and tab without index state',async()=>{const b=await leadViews();b.run("nav('myLeads');businessAPI.search('本人到期');workflowSearchEntries('本人登记已转交').find(r=>r.meta==='线索').action()");assert.equal(b.run('state.page'),'leadDetail');assert.equal(b.run("permissionCanVisit('leadDetail')"),true);assert.match(b.elements.get('#view').innerHTML,/本人登记已转交/);b.run("workflowSearchEntries('本人登记公海').find(r=>r.meta==='线索').action();businessAPI.back()");assert.match(b.elements.get('#view').innerHTML,/本人登记已转交/);assert.doesNotMatch(b.elements.get('#view').innerHTML,/本人登记公海/);b.run('businessAPI.back()');assert.equal(b.run('state.page'),'myLeads');assert.deepEqual(leadRowIds(b),['本人到期']);b.run("nav('course')");assert.match(b.elements.get('#view').innerHTML,/真实数学课/);assert.equal(b.run("businessAPI.leadDetail('不可见线索')"),false);});
test('setup guide belongs to home only and terminal lead row actions remain meaningful',async()=>{const b=await leadViews({superadmin:true});b.run("nav('home')");assert.match(b.elements.get('#view').innerHTML,/开始使用/);for(const page of ['quickRegister','leadTodo','myLeads','leadManage','course']){b.run(`nav('${page}')`);assert.doesNotMatch(b.elements.get('#view').innerHTML,/开始使用/)}b.run("nav('myLeads');businessAPI.leadTab('leadMineTab','archived');businessAPI.leadExpand('本人已归档')");let h=b.elements.get('#view').innerHTML;assert.match(h,/'lead.reactivate'/);assert.doesNotMatch(h,/'lead.followup'|'lead.archive'/);b.run("businessAPI.leadTab('leadMineTab','converted');businessAPI.leadExpand('本人已报名')");h=b.elements.get('#view').innerHTML;assert.doesNotMatch(h,/'lead.release'|'lead.archive'|'lead.claim'/);});
